sources.hypot:
main=()=>{
let total=0.0 let start=time_ns()
loop i in [0..4000000) {
let x=((i%1024) as float64)*0.125+1.0
let y=(((i*7)%1024) as float64)*0.0625+1.0
total+=hypot(x y)
}
let elapsed=time_ns()-start
printl"{total} {elapsed}"
return 0
}

sources.norm:
main=()=>{
let values=[loop i in [0..262144) ((i%1024) as float64)*0.125+1.0]
let total=0.0 let start=time_ns()
loop step in [0..128) {
values[0]=(step as float64)*0.125
total+=norm(values)
}
let elapsed=time_ns()-start
printl"{total} {elapsed}"
return 0
}
